pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 1 ether && depositAmount < 1000 ether);
        vm.assume(cashOutAmount <= depositAmount);
        // Deposit with fuzzed actor
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();
        // CashOut from the actor
        vm.prank(actor);
        try c.CashOut(cashOutAmount) {} catch {}
        // Invariant: actor's balance must equal their net deposit minus net withdrawals (which here is deposit - cashOut since they only did one of each)
        uint256 expectedBalance = depositAmount - cashOutAmount;
        assertEq(c.balances(actor), expectedBalance, "Invariant violated: actor's balance should reflect net deposits");
    }
}

