pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount) public {
        // Admissible domain: deposit > MinDeposit, cashOut <= deposit, deposit + cashOut doesn't overflow
        bound(depositAmount, 1 ether + 1, type(uint256).max / 2);
        bound(cashOutAmount, 1, depositAmount);

        address zero = address(0);

        // Fund the deposit
        vm.deal(address(this), depositAmount);
        c.Deposit{value: depositAmount}();

        // Record balance of zero before cashOut
        uint256 balanceBefore = c.balances(zero);

        // CashOut from zero address — must prank as zero to meet balances[msg.sender] check
        vm.deal(zero, 0); // optional, zero already has 0 balance
        vm.prank(zero);
        try c.CashOut(cashOutAmount) returns () {} catch {}

        uint256 balanceAfter = c.balances(zero);

        // Rule: after CashOut, the balance of address(0) should decrease by cashOutAmount
        assertEq(balanceBefore - cashOutAmount, balanceAfter);
    }
}

