pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount, address sender) public {
        // Restrict to admissible domain: deposit must be above minimum, sender not zero address
        vm.assume(sender != address(0));
        depositAmount = bound(depositAmount, 1 ether + 1, type(uint256).max);
        cashOutAmount = bound(cashOutAmount, 0, depositAmount);
        // Ensure sender has enough Ether for deposit
        vm.deal(sender, depositAmount);
        // Simulate deposit from sender
        vm.prank(sender);
        c.Deposit{value: depositAmount}();
        // Compute invariant: contract balance should equal sum of all balances of known participants
        uint256 contractBalance = address(c).balance;
        uint256 sumBalances = c.balances(sender) + c.balances(address(0));
        assertTrue(contractBalance == sumBalances);
    }
}

